test('都道府県ごとの送料', () => {
  assert.equal(shippingFee({ items: [{ sku: 'a', price: 1000, qty: 1 }], prefecture: '東京都' }), 600)
  assert.equal(shippingFee({ items: [{ sku: 'a', price: 1000, qty: 1 }], prefecture: '北海道' }), 1200)
})

test('送料無料の判定は税抜金額で行う', () => {
  // 税抜4,600円（税込5,060円）は無料にならない
  assert.equal(shippingFee({ items: [{ sku: 'a', price: 4600, qty: 1 }], prefecture: '東京都' }), 600)
  // 税抜5,000円ちょうどは無料
  assert.equal(shippingFee({ items: [{ sku: 'a', price: 5000, qty: 1 }], prefecture: '東京都' }), 0)
})

test('クーポン適用後の税抜金額で無料判定する', () => {
  // 5,500円 - 600円 = 4,900円 → 無料にならない
  assert.equal(
    shippingFee({ items: [{ sku: 'a', price: 5500, qty: 1 }], prefecture: '東京都', couponDiscount: 600 }),
    600
  )
  // 5,600円 - 600円 = 5,000円ちょうど → 無料
  assert.equal(
    shippingFee({ items: [{ sku: 'a', price: 5600, qty: 1 }], prefecture: '東京都', couponDiscount: 600 }),
    0
  )
  // couponDiscount 未指定は 0 円扱い
  assert.equal(shippingFee({ items: [{ sku: 'a', price: 5000, qty: 1 }], prefecture: '東京都' }), 0)
})

test('無料条件を満たした沖縄県・離島は中継料800円がかかる', () => {
  assert.equal(shippingFee({ items: [{ sku: 'a', price: 6000, qty: 1 }], prefecture: '沖縄県' }), 800)
  assert.equal(
    shippingFee({ items: [{ sku: 'a', price: 6000, qty: 1 }], prefecture: '東京都', remoteIsland: true }),
    800
  )
})

test('無料条件を満たさない沖縄県・離島は通常送料のみで中継料は足さない', () => {
  assert.equal(shippingFee({ items: [{ sku: 'a', price: 1000, qty: 1 }], prefecture: '沖縄県' }), 1500)
  assert.equal(
    shippingFee({ items: [{ sku: 'a', price: 1000, qty: 1 }], prefecture: '東京都', remoteIsland: true }),
    600
  )
})
